from collections import deque


def transform(grid):
    """Restore noisy rectangles by filling the bounding box of each major component."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    seen = [[False] * w for _ in range(h)]
    rectangles = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if seen[r][c] or color == background:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            area = (r1 - r0 + 1) * (c1 - c0 + 1)
            if area >= 4 and len(cells) / area >= 0.55:
                rectangles.append((len(cells) / area, color, r0, r1, c0, c1))
    out = [[background] * w for _ in range(h)]
    score = [[-1.0] * w for _ in range(h)]
    for density, color, r0, r1, c0, c1 in sorted(rectangles, reverse=True):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if density > score[r][c]:
                    out[r][c] = color
                    score[r][c] = density
    return out

